import 'dart:async';import 'dart:convert';import 'package:flutter/material.dart';import 'package:http/http.dart' as http;import 'package:flutter_tts/flutter_tts.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.blue),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{static const api='https://ai-based-patient-gesture-communication.onrender.com';final t=FlutterTts();List a=[];Timer? timer;String? spoken;
void initState(){super.initState();load();timer=Timer.periodic(const Duration(seconds:3),(_)=>load());}void dispose(){timer?.cancel();super.dispose();}
Future<void> load()async{try{final r=await http.get(Uri.parse('$api/api/alerts'));if(r.statusCode==200){final d=jsonDecode(r.body) as List;if(mounted)setState(()=>a=d);if(d.isNotEmpty&&d.first['status']=='New'){final k='${d.first['id']}';if(spoken!=k){spoken=k;await t.setLanguage(d.first['language']=='kn'?'kn-IN':d.first['language']=='hi'?'hi-IN':'en-IN');await t.speak('${d.first['message']}. Room ${d.first['room']}. Bed ${d.first['bed']}');}}}}catch(_){}}Future<void> act(String id,String x)async{await http.patch(Uri.parse('$api/api/alerts/$id'),headers:{'Content-Type':'application/json'},body:jsonEncode({'action':x}));load();}
Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('CareGesture AI'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:a.isEmpty?const Center(child:Text('No patient alerts',style:TextStyle(fontSize:22))):ListView.builder(padding:const EdgeInsets.all(14),itemCount:a.length,itemBuilder:(c,i){final x=a[i],critical=x['priority']=='Critical';return Card(color:critical?Colors.red.shade50:null,child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(critical?'🚨 CRITICAL ALERT':'PATIENT ALERT',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900,color:critical?Colors.red:Colors.blue)),const SizedBox(height:10),Text('${x['message']}',style:const TextStyle(fontSize:38,fontWeight:FontWeight.w900)),Text('Room ${x['room']} · Bed ${x['bed']}',style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800)),Text('Patient ${x['patientId']} · ${x['status']}'),Wrap(spacing:7,children:[ElevatedButton.icon(onPressed:()=>t.speak('${x['message']}. Room ${x['room']}. Bed ${x['bed']}'),icon:const Icon(Icons.volume_up),label:const Text('Voice')),OutlinedButton(onPressed:()=>act('${x['id']}','acknowledge'),child:const Text('Acknowledge')),OutlinedButton(onPressed:()=>act('${x['id']}','resolve'),child:const Text('Resolve')),OutlinedButton(onPressed:()=>act('${x['id']}','escalate'),child:const Text('Escalate'))])])));});}}